#include <iostream>
#include <utility>
using namespace std;

int main(void)
{
  int n, a[100];
  string s[100];

  cin >> n;
  for(int i = 0; i < n; i++) cin >> s[i] >> a[i];

  pair<int, int> m = {a[0], 0};
  for(int i = 1; i < n; i++) m = min(m, {a[i], i});
  int p = m.second;

  for(int i = 0; i < n; i++) cout << s[(p+i)%n] << endl;

  return 0;
}
